"use client";
import { Cell, Pie, PieChart, ResponsiveContainer } from "recharts";
import { useState } from "react";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { cx } from "../../utils/cx";
import { formatNumber } from "./chart-card";
import { ChartFrame, safeRatio, sum, WeekSwitcher } from "./pro-chart";
export interface SleepMetric {
  label: string;
  detail: string;
  value: number;
  max: number;
  color?: string;
}
export interface SleepWeek {
  id: string;
  label: string;
  metrics: SleepMetric[];
}
export interface SleepScoreCardProps {
  title?: string;
  metrics?: SleepMetric[];
  weeks?: SleepWeek[];
  defaultWeek?: string;
  onWeekChange?: (id: string) => void;
  className?: string;
}
export const SLEEP_METRICS: SleepMetric[] = [
  {
    label: "Duration",
    detail: "7h 50m",
    value: 49,
    max: 50,
    color: "var(--color-chart-5)",
  },
  {
    label: "Bedtime",
    detail: "20m earlier",
    value: 29,
    max: 30,
    color: "var(--color-chart-3)",
  },
  {
    label: "Interruptions",
    detail: "5m wake up",
    value: 20,
    max: 20,
    color: "var(--color-chart-6)",
  },
];
const WEEKS: SleepWeek[] = [
  {
    id: "previous",
    label: "22 Jun - 28 Jun",
    metrics: SLEEP_METRICS.map((m, i) => ({
      ...m,
      value: m.value - [5, 4, 2][i]!,
    })),
  },
  { id: "current", label: "29 Jun - 5 Jul", metrics: SLEEP_METRICS },
  {
    id: "next",
    label: "6 Jul - 12 Jul",
    metrics: SLEEP_METRICS.map((m, i) => ({
      ...m,
      value: m.value - [2, 1, 0][i]!,
    })),
  },
];
export function SleepScoreCard({
  title = "Sleep score",
  metrics,
  weeks: suppliedWeeks,
  defaultWeek = "current",
  onWeekChange,
  className,
}: SleepScoreCardProps = {}) {
  const weeks = suppliedWeeks ?? WEEKS;
  const [active, setActive] = useState<number | null>(null);
  const [week, setWeek] = useState(
      Math.max(
        0,
        weeks.findIndex((w) => w.id === defaultWeek),
      ),
    ),
    reduced = useHydratedReducedMotion(),
    current = weeks[week],
    items = metrics ?? current?.metrics ?? [],
    score = sum(items.map((m) => m.value)),
    maximum = sum(items.map((m) => m.max)),
    change = (delta: number) => {
      const next = (week + delta + weeks.length) % Math.max(1, weeks.length);
      setWeek(next);
      setActive(null);
      if (weeks[next]) onWeekChange?.(weeks[next]!.id);
    };
  const plotItems = items.map((m) => ({
    ...m,
    value: safeRatio(m.value, m.max) * Math.max(0, m.max),
  }));
  const remainder = Math.max(0, maximum - sum(plotItems.map((m) => m.value)));
  return (
    <ChartFrame
      title={title}
      heading={
        safeRatio(score, maximum) >= 0.9
          ? "Excellent"
          : safeRatio(score, maximum) >= 0.75
            ? "Good"
            : "Fair"
      }
      padding="inset"
      className={cx("rounded-[20px]", className)}
      height={330}
      action={
        <WeekSwitcher
          compact
          className="dark:border-background-primary-default"
          interactive={suppliedWeeks != null || onWeekChange != null}
          label={current?.label ?? "This week"}
          onPrevious={() => change(-1)}
          onNext={() => change(1)}
        />
      }
    >
      <div className="relative -mt-2 h-[104px] shrink-0">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={[{ value: 1 }]}
              dataKey="value"
              innerRadius={37}
              outerRadius={52}
              stroke="none"
              fill="var(--color-chart-track)"
              isAnimationActive={false}
            />
            <Pie
              data={[...plotItems, { value: remainder }]}
              dataKey="value"
              innerRadius={37}
              outerRadius={52}
              startAngle={90}
              endAngle={-270}
              paddingAngle={4}
              cornerRadius={9}
              stroke="none"
              isAnimationActive={!reduced}
              animationDuration={450}
              animationEasing="ease"
              onMouseEnter={(_, index) =>
                setActive(index < items.length ? index : null)
              }
              onMouseLeave={() => setActive(null)}
            >
              {plotItems.map((m, i) => (
                <Cell
                  key={m.label}
                  fill={m.color ?? `var(--color-chart-${i + 3})`}
                  opacity={active != null && active !== i ? 0.7 : 1}
                  className="transition-opacity duration-200 ease-out"
                />
              ))}
              <Cell
                fill="transparent"
                opacity={1}
                className="transition-opacity duration-200 ease-out"
              />
            </Pie>
          </PieChart>
        </ResponsiveContainer>
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
          <span
            key={active ?? "total"}
            className="animate-number-fade text-display-4-medium text-text-primary tabular-nums"
          >
            {formatNumber(
              active == null ? score : (items[active]?.value ?? score),
            )}
          </span>
        </div>
      </div>
      <div className="flex w-full flex-1 flex-col rounded-2lg bg-background-inner-default ps-2.5">
        {items.map((m, i) => (
          <div
            key={m.label}
            className={cx(
              "flex w-full flex-1 items-center justify-between py-2 pe-2.5",
              i < items.length - 1 && "border-b border-separator-border-strong",
            )}
          >
            <div className="flex items-center gap-1.5">
              <span
                className="size-3 shrink-0 rounded-[4px]"
                style={{ background: m.color ?? `var(--color-chart-${i + 3})` }}
              />
              <span className="text-body-regular whitespace-nowrap text-text-secondary">
                {m.label}: {m.detail}
              </span>
            </div>
            <span className="text-body-medium whitespace-nowrap text-text-primary tabular-nums">
              {m.value}/{m.max}
            </span>
          </div>
        ))}
      </div>
    </ChartFrame>
  );
}
